  async function renderAssets(){const box=$('assets');box.innerHTML=state.assets.map((a)=>'<label class="tc-asset"><input type="checkbox" data-tc-asset value="'+esc(a.id)+'" '+(state.photos.includes(a.id)?'checked':'')+'><img alt=""><span>'+esc(a.caption||a.name||'사진')+'</span></label>').join('')||'추가한 사진이 없습니다.';await Promise.all(state.assets.map(async(a)=>{try{const result=await api.imageDataUrl(a.path);const image=box.querySelector('[data-tc-asset][value="'+CSS.escape(a.id)+'"]')?.parentElement.querySelector('img');if(image&&result&&result.dataUrl)image.src=result.dataUrl;else if(image&&result&&result.url)image.src=result.url;}catch(_){}}));box.querySelectorAll('[data-tc-asset]').forEach((x)=>x.addEventListener('change',()=>{state.photos=Array.from(box.querySelectorAll('[data-tc-asset]:checked')).map((i)=>i.value);}));}
