  const AUTO_STAGE_ORDER=['resolve','collect','save','keywords'];
  const AUTO_STAGE_LABELS={resolve:'주소 확인',collect:'상품 수집',save:'근거 검토·저장',keywords:'키워드 후보'};
  function renderAutoProgress(activeKey,errorKey){
    const box=$('auto-progress');if(!box)return;
    const activeIndex=AUTO_STAGE_ORDER.indexOf(activeKey);
    const errorIndex=errorKey?AUTO_STAGE_ORDER.indexOf(errorKey):-1;
    box.innerHTML=AUTO_STAGE_ORDER.map((key,i)=>{
      let cls='tc-auto-step';
      if(errorIndex>=0){cls+=i<errorIndex?' tc-step-done':i===errorIndex?' tc-step-error':'';}
      else if(activeIndex>=0){cls+=i<activeIndex?' tc-step-done':i===activeIndex?' tc-step-active':'';}
      return '<span class="'+cls+'" data-tc-auto-stage="'+key+'">'+esc(AUTO_STAGE_LABELS[key])+'</span>';
    }).join('');
  }
